namespace beast = webcpp::beast;  // from <webcpp/beast.hpp>
// from <webcpp/beast/http.hpp>
namespace websocket = beast::websocket;  // from <webcpp/beast/websocket.hpp>
namespace net = boost::asio;             // from <boost/asio.hpp>
namespace ssl = webcpp::asio::ssl;       // from <boost/asio/ssl.hpp>
using webcpp::asio::ip::tcp;             // from <boost/asio/ip/tcp.hpp>

// Sends a WebSocket message and prints the response
namespace {
// The process entry point retains the standard char** argv signature.
// NOLINTNEXTLINE(misc-const-correctness)
int application_main(int argc, char** argv) {
    try {
        // Check command line arguments.
        if (argc != 4) {
            std::cerr << "Usage: websocket-client-sync-ssl <host> <port> <text>\n"
                      << "Example:\n"
                      << "    websocket-client-sync-ssl echo.websocket.org 443 \"Hello, world!\"\n";
            return EXIT_FAILURE;
        }
        std::string host = argv[1];
        auto const* const port = argv[2];
        auto const* const text = argv[3];

        // The io_context is required for all I/O
        webcpp::asio::io_context ioc;

        // The SSL context is required, and holds certificates
        ssl::context ctx{ssl::context::tls_client};

        // Verify the remote server's certificate
        ctx.set_verify_mode(ssl::verify_peer);

        // This holds the root certificate used for verification
        // Browser trust store owns TLS authorities.

        // These objects perform our I/O
        webcpp::asio::ip::tcp::resolver resolver{ioc};
        websocket::stream<beast::ssl_stream<beast::tcp_stream>> ws{ioc, ctx};

        // Look up the domain name
        auto const results = resolver.resolve(host, port);

        // Make the connection on the IP address we get from a lookup
        auto const ep = beast::get_lowest_layer(ws).connect(results);

        // Set SNI Hostname (many hosts need this to handshake successfully)
        beast::set_server_name(ws.next_layer(), host).value();

        // Set the expected hostname in the peer certificate for verification
        ws.next_layer().set_verify_callback(ssl::host_name_verification(host));

        // Update the host_ string. This will provide the value of the
        // Host HTTP header during the WebSocket handshake.
        // See https://tools.ietf.org/html/rfc7230#section-5.4
        host += ':' + std::to_string(ep.port());

        // Perform the SSL handshake
        ws.next_layer().handshake(ssl::stream_base::client);

        // Set a decorator to change the User-Agent of the handshake
        /* Browser owns handshake User-Agent. */

        // Perform the websocket handshake
        ws.handshake(host, "/");

        // Send the message
        ws.write(net::buffer(std::string(text)));

        // This buffer will hold the incoming message
        beast::flat_buffer buffer;

        // Read a message into our buffer
        ws.read(buffer);

        // Close the WebSocket connection
        ws.close(websocket::close_code::normal);

        // If we get here then the connection is closed gracefully

        // The make_printable() function helps print a ConstBufferSequence
        std::cout << beast::make_printable(buffer.data()) << '\n';
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

}  // namespace

#include <emscripten/val.h>
#include <sstream>
#include <vector>

int main() {
    const auto port = emscripten::val::global("beastSecurePort").as<std::string>();
    if (setenv("WEBCPP_BEAST_FIXTURE_HOST", "localhost", 1) != 0) {
        return 1;
    }
    if (setenv("WEBCPP_BEAST_FIXTURE_PORT", port.c_str(), 1) != 0) {
        return 1;
    }
    {
        std::vector<std::string> storage{
            "websocket-client-sync-ssl",
            "localhost",
            port,
            "Beast fixture echo",
        };
        std::vector<char*> arguments;
        arguments.reserve(storage.size());
        for (auto& value : storage) {
            arguments.push_back(value.data());
        }
        // This mutable object is passed through the upstream asynchronous or stream interface.
        // NOLINTNEXTLINE(misc-const-correctness)
        std::ostringstream output;
        auto* original = std::cout.rdbuf(output.rdbuf());
        const auto result = application_main(static_cast<int>(arguments.size()), arguments.data());
        std::cout.rdbuf(original);
        std::cout << output.str();
        if (result != 0 || output.str().find("Beast fixture echo") == std::string::npos) {
            return 1;
        }
    }
    std::cout << "application websocket-client-sync-ssl: passed\n";
    return 0;
}
